import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"GAMES — Sealed Play & Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"docs/games.md","filePath":"docs/games.md"}`),a={name:`docs/games.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="games-—-sealed-play-strategy" tabindex="-1">GAMES — Sealed Play &amp; Strategy <a class="header-anchor" href="#games-—-sealed-play-strategy" aria-label="Permalink to “GAMES — Sealed Play &amp; Strategy”">​</a></h1><p><strong>The Framework:</strong> Games where the outcome is decidable. Not randomness, not bluffing — pure strategy in bounded state space.</p><p>Each game in trinity structure:</p><ol><li><strong>SEALED</strong> — proof that the game is decidable (finite state, perfect information)</li><li><strong>HONEST BOUNDARY</strong> — what the theorem cannot guarantee (human play, luck, meaning)</li><li><strong>STRATEGIC PAIR</strong> — the opening question (what makes this game worth playing?)</li></ol><hr><h2 id="the-domains" tabindex="-1">The Domains <a class="header-anchor" href="#the-domains" aria-label="Permalink to “The Domains”">​</a></h2><h3 id="chess-64-theorems" tabindex="-1">Chess (64 theorems) <a class="header-anchor" href="#chess-64-theorems" aria-label="Permalink to “Chess (64 theorems)”">​</a></h3><p><strong>Sealed:</strong> The board is 8×8 = 64 squares. Piece moves are finite. The 50-move rule caps runtime. Shannon count: ~10^120 game tree is incomputable, but with bounded moves it&#39;s finite.</p><p><strong>Honest Boundary:</strong> No proof that chess has a &quot;correct&quot; move. Only that the game halts.</p><p><strong>Strategic Question:</strong> <em>If we could solve chess perfectly, would the game still be worth playing?</em></p><h3 id="nim-1-sprague-grundy" tabindex="-1">Nim (1 + Sprague-Grundy) <a class="header-anchor" href="#nim-1-sprague-grundy" aria-label="Permalink to “Nim (1 + Sprague-Grundy)”">​</a></h3><p><strong>Sealed:</strong> The nim-sum (XOR) is the P-position test. A zero nim-sum loses for the mover (Bouton&#39;s theorem). Every non-zero position has a move to zero.</p><p><strong>Honest Boundary:</strong> No proof about real Nim matches — only abstract Nim.</p><p><strong>Strategic Question:</strong> <em>Does knowing the winning strategy spoil the game or enhance it?</em></p><h3 id="matching-8-theorems" tabindex="-1">Matching (8 theorems) <a class="header-anchor" href="#matching-8-theorems" aria-label="Permalink to “Matching (8 theorems)”">​</a></h3><p><strong>Sealed:</strong> Perfect matching requires an even number of people. Stable matching halts in at most n² proposals (Gale-Shapley). Pairing is a fixed-point-free involution.</p><p><strong>Honest Boundary:</strong> No proof that happiness results from a &quot;stable&quot; match.</p><p><strong>Strategic Question:</strong> <em>If we could compute the perfect match for you, would it be better than finding it yourself?</em></p><hr><h2 id="playing-the-games" tabindex="-1">Playing the Games <a class="header-anchor" href="#playing-the-games" aria-label="Permalink to “Playing the Games”">​</a></h2><p>Each game folder contains:</p><ol><li><strong>Proof</strong> — link to sealed theorem</li><li><strong>Interactive player</strong> — play against the sealed logic (coming)</li><li><strong>Strategy guide</strong> — openings, endgames, decision trees</li><li><strong>Paradox</strong> — the open question about playing vs. solving</li></ol><p><strong>The Honest Scope:</strong> These games are DECIDABLE but not PLAYABLE at scale. Chess has 10^120 positions (incomputable), but with perfect play it&#39;s either a draw or a win for White or Black (unknown). Nim is instantly solved by XOR. Matching is solved in polynomial time. <strong>Knowing the answer changes the game.</strong></p><hr><h2 id="why-games-matter" tabindex="-1">Why Games Matter <a class="header-anchor" href="#why-games-matter" aria-label="Permalink to “Why Games Matter”">​</a></h2><p>A sealed game proves:</p><ul><li><strong>Decidability</strong> — this outcome <em>can</em> be computed (vs. uncomputable games like Go, which has ~10^170 positions)</li><li><strong>Bounds</strong> — runtime is bounded (no infinite loops, stalemate is forced)</li><li><strong>Strategy</strong> — optimal play exists (even if we don&#39;t know it)</li></ul><p>But it cannot prove:</p><ul><li><strong>Beauty</strong> — why the game is fun</li><li><strong>Meaning</strong> — what victory means</li><li><strong>Community</strong> — why humans play together</li></ul><p><strong>The paradox:</strong> A solved game is a dead game. Yet solving it reveals its structure, and structure is beautiful.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};